def shortest_path(graph, source, target):

    def neighbors_with_weight(node):
        for neighbor, weight in graph.get(node, []):
            yield (neighbor, weight)

    def find_shortest_path(current_node, previous_nodes, distance, path):
        if current_node == source:
            path.insert(0, source)
            return (True, path)
        if current_node not in distance:
            return (False, [])
        for neighbor, weight in neighbors_with_weight(current_node):
            if neighbor in previous_nodes and distance[neighbor] + weight < distance[current_node]:
                distance[current_node] = distance[neighbor] + weight
                path.pop(0)
                path.insert(0, neighbor)
                new_previous_nodes = previous_nodes.copy()
                new_previous_nodes[neighbor] = current_node
                found, new_path = find_shortest_path(neighbor, new_previous_nodes, distance, path)
                if found:
                    return (True, new_path)
        return (False, [])
    distance = {source: 0}
    path = [source]
    previous_nodes = {source: None}
    found, path = find_shortest_path(target, previous_nodes, distance, path)
    if found:
        return (distance[target], path)
    else:
        return (float('inf'), None)
