from collections import deque

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)
    queue = deque([(source, [])])
    visited = set()
    shortest_distance = float('inf')
    shortest_path = None
    while queue:
        current_node, path = queue.popleft()
        visited.add(current_node)
        if current_node == target:
            if len(path) < shortest_distance:
                shortest_distance = len(path)
                shortest_path = path[:]
            elif len(path) == shortest_distance:
                shortest_path = sorted(path + [target])
        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [current_node]))
    return (shortest_distance, shortest_path) if shortest_path else (float('inf'), None)
graph = {'A': [('B', 1), ('C', 4)], 'B': [('C', 1), ('D', 2)], 'C': [('D', 3)], 'D': [('E', 1)], 'E': []}
print(shortest_path(graph, 'A', 'E'))
print(shortest_path(graph, 'A', 'F'))
